import subprocess
sh_src = out_root.parent / 'preset_assets' / 'data.sh'
bg = out_root / 'background'
bg.mkdir(parents=True, exist_ok=True)
if not sh_src.exists():
    log('preset_assets/data.sh 缺失', 'ERR')
else:
    shutil.copy(sh_src, bg / 'data.sh')
    r = subprocess.run(['bash', 'data.sh'], cwd=str(bg), capture_output=True, text=True)
    if r.returncode != 0:
        log('data.sh 失败: ' + r.stderr, 'ERR')
    else:
        log('panorama_equirect.png 已生成', 'OK')

# 清理多余文件
# realms 里不该存在的残留
extra = [
    out_root / 'realms' / 'no_realms.png',
    out_root / 'realms' / 'snapshot_realms.png',
]
for p in extra:
    if p.exists():
        p.unlink()
        log('删除残留: ' + str(p.relative_to(out_root)), 'OK')

# friends 里如果有历史遗留的 .mcmeta，也清掉
fd = out_root / 'friends'
if fd.is_dir():
    for f in fd.iterdir():
        if f.is_file() and f.name.endswith('.mcmeta'):
            f.unlink()
            log('删除残留: ' + str(f.relative_to(out_root)), 'OK')
log('清理完成', 'OK')
